// Fresh independent four-variable verifier. No author or historical executable is imported.
#include <array>
#include <vector>
#include <iostream>
#include <fstream>
#include <sstream>
#include <algorithm>
#include <stdexcept>
#include <cstdint>
#include "independent_chart.h"
using namespace std;
using Z=uint32_t; using M=array<Z,64>; using PolyN=array<array<Z,16>,64>;
constexpr uint64_t PRIME=1000000009;
Z add(Z a,Z b){uint64_t z=uint64_t(a)+b;return z>=PRIME?z-PRIME:z;}
Z sub(Z a,Z b){return a>=b?a-b:a+PRIME-b;}
Z mul(Z a,Z b){return uint64_t(a)*b%PRIME;}
Z power(Z a,uint64_t n){Z r=1;for(;n;n>>=1,a=mul(a,a))if(n&1)r=mul(r,a);return r;}
Z inv(Z a){if(!a)throw runtime_error("zero inverse");return power(a,PRIME-2);}
void require(bool v,const string&s){if(!v)throw runtime_error(s);}
uint64_t inversions=0,inverse_entry_checks=0,polynomial_checks=0,determinants=0;
M product(const M&a,const M&b){M c{};for(int i=0;i<8;i++)for(int j=0;j<8;j++){__uint128_t t=0;for(int k=0;k<8;k++)t+=uint64_t(a[8*i+k])*b[8*k+j];c[8*i+j]=t%PRIME;}return c;}
M inverse_checked(const M&a,Z target_det){Z t[8][16]{};for(int i=0;i<8;i++)for(int j=0;j<8;j++){t[i][j]=a[8*i+j];t[i][8+j]=(i==j);}Z det=1;for(int k=0;k<8;k++){int r=k;while(r<8&&!t[r][k])r++;require(r<8,"singular Green inverse");if(r!=k){for(int j=0;j<16;j++)swap(t[r][j],t[k][j]);det=sub(0,det);}Z pivot=t[k][k];det=mul(det,pivot);Z v=inv(pivot);for(int j=0;j<16;j++)t[k][j]=mul(t[k][j],v);for(int i=0;i<8;i++)if(i!=k){Z f=t[i][k];for(int j=0;j<16;j++)t[i][j]=sub(t[i][j],mul(f,t[k][j]));}}
require(det==target_det,"Green determinant != exact branch guard");M b{};for(int i=0;i<8;i++)for(int j=0;j<8;j++)b[8*i+j]=t[i][8+j];M l=product(a,b),r=product(b,a);for(int i=0;i<64;i++){require(l[i]==Z(i/8==i%8)&&r[i]==Z(i/8==i%8),"two-sided inverse mismatch");inverse_entry_checks+=2;}inversions++;return b;}
struct Label{int stage,branch;array<int,4>edges;};
array<array<Z,24>,2> gains(Z root){array<array<Z,24>,2>g{};for(int s=0;s<2;s++){for(int e=0;e<7;e++)g[s][e]=1;for(int e=7;e<24;e++){Z a=pairs[s][e-7][0],b=pairs[s][e-7][1];Z real=sub(mul(a,a),mul(b,b)),imag=mul(2,mul(a,b)),den=add(mul(a,a),mul(b,b));g[s][e]=mul(add(real,mul(root,imag)),inv(den));}}return g;}
PolyN reconstruct(const Label&lab,Z root){auto g=gains(root);array<M,16> vals{};for(int mask=0;mask<16;mask++){array<M,2>sums{};Z delta=1;for(int s=0;s<2;s++)for(int b=0;b<3;b++){M iw{};for(int j=0;j<8;j++)iw[8*j+j]=1;Z h=1;for(int j=0;j<8;j++){int edge=8*b+j;Z weight=g[s][edge];if(s==lab.stage)for(int k=0;k<4;k++)if(edge==lab.edges[k]&&!(mask&(1<<k)))weight=0;h=mul(h,weight);int dst=cycles[s][b][j],src=cycles[s][b][(j+7)%8];iw[8*dst+src]=sub(iw[8*dst+src],weight);}Z guard=sub(1,h);require(guard,"Boolean interpolation pole");delta=mul(delta,guard);M green=inverse_checked(iw,guard);for(int e=0;e<64;e++)sums[s][e]=add(sums[s][e],green[e]);}vals[mask]=product(sums[1],sums[0]);for(Z&z:vals[mask])z=mul(z,delta);}
for(int bit=1;bit<16;bit<<=1)for(int mask=0;mask<16;mask++)if(mask&bit)for(int e=0;e<64;e++)vals[mask][e]=sub(vals[mask][e],vals[mask^bit][e]);PolyN n{};for(int e=0;e<64;e++)for(int mask=0;mask<16;mask++)n[e][mask]=vals[mask][e];return n;}
vector<int> supp5,supp4,hpos;int maskpos[16];int predecessor[625];bool expected[625];
int cyclic_tv(int a,int b,int c,int d){return abs(a-b)+abs(b-c)+abs(c-d)+abs(d-a);}
void setup(){for(int m=0;m<16;m++){int v=0;for(int j=3;j>=0;j--)v=5*v+((m>>j)&1);maskpos[m]=v;}for(int a=0;a<3;a++)for(int b=0;b<3;b++)for(int c=0;c<3;c++)for(int d=0;d<3;d++)hpos.push_back(a+5*b+25*c+125*d);for(int i=0;i<625;i++){int t=i,low=5,hi=-1;for(int j=0;j<4;j++){low=min(low,t%5);hi=max(hi,t%5);t/=5;}predecessor[i]=low>=1?i-156:-1;expected[i]=hi<=3&&hi-low<=2&&cyclic_tv(i%5,(i/5)%5,(i/25)%5,(i/125)%5)<=4;}for(int a=0;a<4;a++)for(int b=0;b<4;b++)for(int c=0;c<4;c++)for(int d=0;d<4;d++)if(max({a,b,c,d})-min({a,b,c,d})<=2&&cyclic_tv(a,b,c,d)<=4){supp5.push_back(a+5*b+25*c+125*d);supp4.push_back(64*a+16*b+4*c+d);}require(supp5.size()==126,"support dimension");}
using HTable=array<array<Z,313>,64>;
HTable hadamard(const PolyN&n,const PolyN&bar){HTable h{};for(int e=0;e<64;e++){__uint128_t acc[313]{};for(int a=0;a<16;a++)for(int b=0;b<16;b++)acc[maskpos[a]+maskpos[b]]+=uint64_t(n[e][a])*bar[e][15^b];for(int j:hpos){h[e][j]=acc[j]%PRIME;int a=j%5,b=(j/5)%5,c=(j/25)%5,d=(j/125)%5;require(!h[e][j]||(max({a,b,c,d})-min({a,b,c,d})<=1&&cyclic_tv(a,b,c,d)<=2),"H27 support violation");}}return h;}
array<int,2> pair_at(int q){for(int a=0;a<8;a++)for(int b=a+1;b<8;b++)if(q--==0)return {a,b};throw runtime_error("pair index");}
vector<Z> quotient_row(const HTable&h,Z hol,int window){auto rows=pair_at(window/28),cols=pair_at(window%28);int a=8*rows[0]+cols[0],b=8*rows[0]+cols[1],c=8*rows[1]+cols[0],d=8*rows[1]+cols[1];__uint128_t left[625]{},right[625]{};for(int i:hpos)for(int j:hpos){left[i+j]+=uint64_t(h[a][i])*h[d][j];right[i+j]+=uint64_t(h[b][i])*h[c][j];}Z p[625]{},q[625]{};for(int i=0;i<625;i++){p[i]=sub(left[i]%PRIME,right[i]%PRIME);q[i]=p[i];if(predecessor[i]>=0)q[i]=add(q[i],mul(hol,q[predecessor[i]]));require(expected[i]||q[i]==0,"unprojected quotient violates degree/support");}for(int i=0;i<625;i++){Z r=q[i];if(predecessor[i]>=0)r=sub(r,mul(hol,q[predecessor[i]]));require(r==p[i],"full polynomial multiplication-back mismatch");}polynomial_checks++;vector<Z>out;for(int i:supp5)out.push_back(q[i]);return out;}
Z determinant(vector<vector<Z>>a){int n=a.size();require(n==126,"minor dimension");Z det=1;for(int k=0;k<n;k++){int r=k;while(r<n&&!a[r][k])r++;if(r==n)return 0;if(r!=k){swap(a[r],a[k]);det=sub(0,det);}Z pv=a[k][k];det=mul(det,pv);Z pinv=inv(pv);for(int i=k+1;i<n;i++){Z f=mul(a[i][k],pinv);a[i][k]=0;for(int j=k+1;j<n;j++)a[i][j]=sub(a[i][j],mul(f,a[k][j]));}}determinants++;return det;}
Z holonomy(const Label&l,Z root){auto g=gains(root);Z h=1;for(int e=8*l.branch;e<8*l.branch+8;e++)h=mul(h,g[l.stage][e]);return h;}
vector<int> find_rows(const HTable&h,Z hol){vector<vector<Z>> basis(126);vector<int>windows;for(int w=0;w<784;w++){auto r=quotient_row(h,hol,w);int pivot=-1;for(int j=0;j<126;j++){if(!r[j])continue;if(!basis[j].empty()){Z f=r[j];for(int k=j;k<126;k++)r[k]=sub(r[k],mul(f,basis[j][k]));}else{pivot=j;break;}}if(pivot>=0){Z v=inv(r[pivot]);for(int j=pivot;j<126;j++)r[j]=mul(r[j],v);basis[pivot]=move(r);windows.push_back(w);if(windows.size()==126)return windows;}}throw runtime_error("rank below126: "+to_string(windows.size()));}
int main(int argc,char**argv){try{setup();bool fixed=argc>1;ifstream input;if(fixed){input.open(argv[1]);require(bool(input),"cannot open frozen minor input");}int labels=0;for(int s=0;s<2;s++)for(int b=1;b<=2;b++)for(int a=8*b;a<8*b+8;a++)for(int c=a+1;c<8*b+8;c++)for(int d=c+1;d<8*b+8;d++)for(int e=d+1;e<8*b+8;e++){Label lab{s,b,{a,c,d,e}};PolyN n=reconstruct(lab,569522298),bar=reconstruct(lab,430477711);for(int conjugate=0;conjugate<2;conjugate++){Z root=conjugate?430477711:569522298;HTable h=conjugate?hadamard(bar,n):hadamard(n,bar);Z hol=holonomy(lab,root);vector<int>wins;Z expected_det=0;if(fixed){int is,ib,ia,ic,id,ie,icj,count;input>>is>>ib>>ia>>ic>>id>>ie>>icj>>count;require(input&&is==s&&ib==b&&ia==a&&ic==c&&id==d&&ie==e&&icj==conjugate&&count==126,"fixed label/order/count mismatch");for(int j=0;j<126;j++){int w;input>>w;require(w>=0&&w<784,"bad fixed window");wins.push_back(w);}input>>expected_det;require(input&&expected_det,"bad expected determinant");}else wins=find_rows(h,hol);vector<vector<Z>>m;for(int w:wins)m.push_back(quotient_row(h,hol,w));Z det=determinant(m);require(det,"zero selected determinant");if(fixed)require(det==expected_det,"fixed determinant mismatch");cout<<s<<' '<<b<<' '<<a<<' '<<c<<' '<<d<<' '<<e<<' '<<conjugate<<" 126";for(int w:wins)cout<<' '<<w;cout<<' '<<det<<'\n';if(labels==0){auto duplicate=m;duplicate[1]=duplicate[0];require(determinant(duplicate)==0,"duplicate-row negative control failed");}}labels++;if(labels%20==0)cerr<<"labels="<<labels<<" quotient_checks="<<polynomial_checks<<'\n';}require(labels==280,"coverage count");if(fixed){string trailing;require(!(input>>trailing),"extra fixed records");}cerr<<"PASS labels="<<labels<<" direct_inversions="<<inversions<<" inverse_entry_checks="<<inverse_entry_checks<<" full_quotient_checks="<<polynomial_checks<<" nonzero_determinants="<<determinants<<'\n';}catch(const exception&e){cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
